function compare_string_characters($a, $b) {
    $a_chars = str_split(str_replace(' ', '', $a));
    $b_chars = str_split(str_replace(' ', '', $b));

    $len_a = count($a_chars);
    $len_b = count($b_chars);

    if ($len_a !== $len_b) {
        return false;
    }

    $min_len = min($len_a, $len_b);
    for ($i = 0; $i < $min_len; $i++) {
        if (strtolower($a_chars[$i]) !== strtolower($b_chars[$i])) {
            return false;
        }
    }

    return true;
}

